sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 offset;
uniform float count;
uniform float2 stretch;
layout(color) uniform half4 color;
uniform float punch;
uniform float angle;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float cell = size.y / (2.475 * max(count, 0.5));
    float a = radians(angle);
    float2 p = coord - size * 0.5 - offset;
    p = float2(cos(a) * p.x + sin(a) * p.y, -sin(a) * p.x + cos(a) * p.y) / (max(abs(stretch), float2(0.01)) * cell);
    float2 e = min(fract(p), 1.0 - fract(p)) * max(abs(stretch), float2(0.01)) * cell;
    float on = mod(floor(p.x) + floor(p.y), 2.0);
    float aa = clamp(min(e.x, e.y) + 0.5, 0.0, 1.0);
    float s = mix(0.5, on, aa);
    if (punch > 0.5) return src * half(1.0 - s);
    float3 base = float3(src.rgb) / float(src.a);
    float3 rgb = mix(base, float3(color.rgb), s * float(color.a));
    return half4(half3(rgb) * src.a, src.a);
}
